def test_parse_content_type_header():
    # Valid case
    header1 = "text/html; charset=utf-8"
    content_type1, params1 = _parse_content_type_header(header1)
    print(f"Header 1: {header1} -> Content-Type: {content_type1}, Params: {params1}")
    assert content_type1 == "text/html"
    assert params1 == {"charset": "utf-8"}

    # Malformed case: parameter without '='
    header2 = "text/html; charset"
    content_type2, params2 = _parse_content_type_header(header2)
    print(f"Header 2: {header2} -> Content-Type: {content_type2}, Params: {params2}")
    # Current behavior: params2 == {"charset": True}
    # Expected behavior: params2 == {}
    assert params2 == {}, f"Expected empty params for malformed header, got {params2}"

    # Mixed case
    header3 = "text/html; charset=utf-8; malformed"
    content_type3, params3 = _parse_content_type_header(header3)
    print(f"Header 3: {header3} -> Content-Type: {content_type3}, Params: {params3}")
    # Current behavior: params3 == {"charset": "utf-8", "malformed": True}
    # Expected behavior: params3 == {"charset": "utf-8"}
    assert params3 == {"charset": "utf-8"}, f"Expected only valid params, got {params3}"

if __name__ == "__main__":
    try:
        test_parse_content_type_header()
        print("Tests passed!")
