from fastapi import FastAPI, APIRouter, FastAPIError
import pytest

def test_include_router_self():
    router = APIRouter()
    with pytest.raises(FastAPIError) as excinfo:
        router.include_router(router)
    assert "You cannot include a router into itself." in str(excinfo.value)

def test_include_app_self():
    app = FastAPI()
    with pytest.raises(FastAPIError) as excinfo:
        app.include_router(app)
    assert "You cannot include a router into itself." in str(excinfo.value)

if __name__ == "__main__":
    try:
        test_include_router_self()
        print("test_include_router_self passed")
    except Exception as e:
        print(f"test_include_router_self failed: {e}")

    try:
        test_include_app_self()
        print("test_include_app_self passed")
